<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $escape($title) ?></title><link rel="stylesheet" href="<?= $escape($assetBasePath) ?>/assets/vendor/bootstrap/bootstrap.min.css"><link rel="stylesheet" href="<?= $escape($assetBasePath) ?>/assets/vendor/fontawesome/css/all.min.css"><style>body{margin:0;background:#f3f6f8;color:#102235;font-family:Arial,sans-serif}.contract-shell{width:min(900px,calc(100% - 2rem));margin:2rem auto}.contract-head,.contract-card,.signature-card{padding:1.5rem;border:1px solid #d8e0e6;border-radius:1rem;background:#fff;box-shadow:0 .5rem 1.5rem #10223512}.contract-head{display:flex;align-items:center;gap:1rem;margin-bottom:1rem}.contract-head img{width:3.5rem;height:3.5rem;object-fit:contain}.contract-card pre{margin:0;white-space:pre-wrap;font:400 1rem/1.65 Georgia,serif}.signature-card{margin-top:1rem}.signature-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.signature-grid label{display:grid;gap:.35rem;font-weight:700}.signature-grid input{min-height:2.8rem;padding:.65rem;border:1px solid #aebbc5;border-radius:.55rem}.full{grid-column:1/-1}.accept{display:flex!important;align-items:flex-start;grid-template-columns:auto 1fr!important}.accept input{width:auto;min-height:auto}.button{padding:.8rem 1rem;border:0;border-radius:.6rem;color:#fff;background:#ed1c24;font-weight:800}.alert{margin-bottom:1rem;padding:1rem;border-radius:.6rem}.success{color:#067647;background:#e8f7ef}.danger{color:#b4232c;background:#fff0f1}.evidence{padding:1rem;border-radius:.65rem;background:#f3f6f8;overflow-wrap:anywhere}@media(max-width:650px){.signature-grid{grid-template-columns:1fr}}@media print{body{background:#fff}.contract-shell{width:100%;margin:0}.signature-card form,.no-print{display:none}.contract-head,.contract-card,.signature-card{box-shadow:none}}</style></head><body><main class="contract-shell"><header class="contract-head"><img src="<?= $escape(